drop database if exists travel_agency;
create database travel_agency;
use travel_agency;

CREATE TABLE branch(
  br_code INT(11) DEFAULT "0" NOT NULL,
  br_street VARCHAR(30) DEFAULT "unknown" NOT NULL,
  br_num INT(4) DEFAULT "0" NOT NULL,
  br_city VARCHAR(30) DEFAULT "unknown" NOT NULL,
  PRIMARY KEY(br_code),
  UNIQUE(br_code)
) engine=InnoDB;


CREATE TABLE worker(
    wrk_AT CHAR(10) DEFAULT 'UNKNOWN' NOT NULL,
    wrk_name VARCHAR(20) DEFAULT 'UNKNOWN' NOT NULL,
    wrk_lname VARCHAR(20) DEFAULT 'UNKNOWN' NOT NULL,
    wrk_salary FLOAT(7.2) NOT NULL,
    wrk_br_code INT(11) DEFAULT '0' NOT NULL,
    PRIMARY KEY (wrk_AT),
    UNIQUE(wrk_AT),
    CONSTRAINT WORKERCODE FOREIGN KEY (wrk_br_code) REFERENCES branch(br_code)
    ON UPDATE CASCADE ON DELETE CASCADE
    )engine=InnoDB;

CREATE TABLE phones(
  ph_br_code INT(11) DEFAULT "0" NOT NULL,
  ph_number CHAR(10) DEFAULT 'unknown' NOT NULL,
  PRIMARY KEY(ph_br_code,ph_number), 
  CONSTRAINT BRCODE FOREIGN KEY(ph_br_code) REFERENCES branch(br_code)
  ON DELETE CASCADE ON UPDATE CASCADE
) engine=InnoDB;

CREATE TABLE admin(
    adm_AT CHAR(10) NOT NULL,
    adm_type ENUM('LOGISTICS','ADMINISTRATIVE','ACCOUNTING'),
   adm_diploma VARCHAR(200) NOT NULL,
   PRIMARY KEY (adm_AT),
   CONSTRAINT ADMINAT FOREIGN KEY(adm_AT) REFERENCES worker(wrk_AT)
   ON UPDATE CASCADE ON DELETE CASCADE 
   )engine=InnoDB; 
   
CREATE TABLE manages(
  mng_adm_AT CHAR(10)  DEFAULT 'unknown' NOT NULL,
  mng_br_code INT(11) DEFAULT '0' NOT NULL,
  PRIMARY KEY(mng_adm_AT,mng_br_code),
  CONSTRAINT ADMAT FOREIGN KEY (mng_adm_AT) REFERENCES admin(adm_AT),
  CONSTRAINT BRANCHCODE FOREIGN KEY (mng_br_code) REFERENCES branch(br_code)
  ON UPDATE CASCADE ON DELETE CASCADE
) engine=InnoDB;

 
 CREATE TABLE driver(
    drv_AT CHAR(10) DEFAULT 'UNKNOWN' NOT NULL,
    drv_license ENUM('A','B','C','D'),
    drv_route ENUM('LOCAL','ABROAD'),
    drv_experience TINYINT(4) NOT NULL,
    PRIMARY KEY (drv_AT),
    CONSTRAINT DRIVERAT FOREIGN KEY (drv_AT) REFERENCES worker(wrk_AT)
    ON UPDATE CASCADE ON DELETE CASCADE 
    )engine=InnoDB;

   CREATE TABLE guide (
 gui_AT CHAR(25) DEFAULT 'unknown' NOT NULL,
 gui_cv TEXT,
 PRIMARY KEY (gui_AT),
CONSTRAINT GUIDETABLE FOREIGN KEY(gui_AT) REFERENCES worker(wrk_AT)
  ON DELETE CASCADE ON UPDATE  CASCADE
  ) engine=InnoDB;
  

 CREATE TABLE languages(
  lng_gui_AT CHAR(10)  DEFAULT 'unknown' NOT NULL,
  lng_language VARCHAR(30) DEFAULT "unknown" NOT NULL,
  PRIMARY KEY(lng_gui_AT,lng_language),
  CONSTRAINT LNGGUIAT FOREIGN KEY (lng_gui_AT) REFERENCES guide(gui_AT)
  ON UPDATE CASCADE ON DELETE CASCADE
) engine=InnoDB;


CREATE TABLE trip(
    tr_id INT(11) DEFAULT '0' NOT NULL,
    tr_departure DATETIME NOT NULL,
    tr_return DATETIME NOT NULL,
    tr_maxseats TINYINT(4) NOT NULL,
    tr_cost FLOAT(7.2) NOT NULL,
    tr_br_code INT(11) DEFAULT '0' NOT NULL,
    tr_gui_AT CHAR(10) DEFAULT 'UNKNOWN' NOT NULL,
    tr_drv_AT CHAR(10) DEFAULT 'UKNOWN' NOT NULL,
    PRIMARY KEY (tr_id),
    CONSTRAINT DRIVE FOREIGN KEY (tr_drv_AT) REFERENCES driver(drv_AT),
    CONSTRAINT BRANCH FOREIGN KEY (tr_br_code) REFERENCES branch (br_code),
    CONSTRAINT GUIDEAT FOREIGN KEY (tr_gui_AT) REFERENCES guide (gui_AT)
    ON UPDATE CASCADE ON DELETE CASCADE
    ) engine=InnoDB;



CREATE TABLE event(
ev_tr_id INT(11) DEFAULT '0' NOT NULL,
ev_start DATETIME NOT NULL,
ev_end DATETIME NOT NULL,
ev_descr TEXT,
PRIMARY KEY(ev_start,ev_tr_id),
CONSTRAINT TRIPEVENT FOREIGN KEY (ev_tr_id) REFERENCES trip(tr_id)
ON UPDATE CASCADE ON DELETE CASCADE
) engine=InnoDB;

CREATE TABLE destination(
  dst_id INT(11) NOT NULL,
  dst_name VARCHAR(50) DEFAULT 'unknown' NOT NULL,
  dst_descr TEXT,
  dst_rtype ENUM('LOCAL','ABROAD'),
  dst_language VARCHAR(30) DEFAULT 'unknown' NOT NULL,
  dst_location INT(11) DEFAULT '0' NOT NULL,
  PRIMARY KEY(dst_id),
  CONSTRAINT DESTINATIONID FOREIGN KEY(dst_location) REFERENCES destination(dst_id)
  ON UPDATE  CASCADE ON DELETE  CASCADE
) engine=InnoDB;

CREATE TABLE travel_to (
  to_tr_id INT(11) NOT NULL,
  to_dst_id INT(11) NOT NULL,
  to_arrival DATETIME NOT NULL,
  to_departure DATETIME NOT NULL,
  PRIMARY KEY(to_tr_id,to_dst_id),
  CONSTRAINT CLCDESTINATION FOREIGN KEY (to_dst_id) REFERENCES destination(dst_id),
  CONSTRAINT TRAVELTOID FOREIGN KEY (to_tr_id) REFERENCES trip(tr_id)
  ON UPDATE CASCADE ON DELETE CASCADE
) engine=InnoDB;


CREATE TABLE reservation(
  res_tr_id INT(11) DEFAULT '0' NOT NULL,
  res_seatnum TINYINT(4) DEFAULT '0' NOT NULL,
  res_name VARCHAR(20) NOT NULL,
  res_lname VARCHAR(20) NOT NULL,
  res_isadult ENUM('ADULT','MINOR'),
  PRIMARY KEY(res_tr_id,res_seatnum),
  CONSTRAINT RESERVATIONID FOREIGN KEY(res_tr_id) REFERENCES trip(tr_id)
  ON UPDATE CASCADE ON DELETE CASCADE
  ) engine=InnoDB;

CREATE TABLE IT(
IT_AT CHAR(10) DEFAULT '0' NOT NULL,
IT_password VARCHAR(10) DEFAULT 'password' NOT NULL,
start_date DATETIME NOT NULL,
end_date DATETIME NOT NULL,
PRIMARY KEY(IT_AT),
CONSTRAINT WORKERIT FOREIGN KEY(IT_AT) REFERENCES worker(wrk_AT)
ON UPDATE CASCADE ON DELETE CASCADE
) engine=InnoDB;

CREATE TABLE offers(
offers_id INT(10) DEFAULT '0' NOT NULL,
offers_period_start DATETIME NOT NULL,
offers_period_end DATETIME NOT NULL,
offers_cost INT(10) DEFAULT '0' NOT NULL,
offers_dst_id INT(11) DEFAULT '0' NOT NULL,
PRIMARY KEY(offers_id),
UNIQUE(offers_id),
CONSTRAINT OFFERSDESTI FOREIGN KEY(offers_dst_id) REFERENCES destination(dst_id)
ON UPDATE CASCADE ON DELETE CASCADE
) engine=InnoDB;

CREATE TABLE reservation_offers(
reservation_offer_id INT(10) DEFAULT '0' NOT NULL,
reservation_name VARCHAR(20) NOT NULL,
reservation_lname VARCHAR(20) NOT NULL,
res_offers_id INT(10) DEFAULT '0' NOT NULL,
advance INT(20) DEFAULT '0' NOT NULL,
PRIMARY KEY(reservation_offer_id,reservation_name,reservation_lname),
UNIQUE(reservation_offer_id),
CONSTRAINT OFFERSID FOREIGN KEY(res_offers_id) REFERENCES offers(offers_id)
ON UPDATE CASCADE ON DELETE CASCADE
) engine=InnoDB;

CREATE TABLE IT_log(
action VARCHAR(20) DEFAULT 'unknown' NOT NULL,
table_name VARCHAR(20) DEFAULT 'unknown' NOT NULL ,
user CHAR(10) DEFAULT '0' NOT NULL,
CONSTRAINT USERIT FOREIGN KEY(user) REFERENCES IT(IT_AT)
ON UPDATE CASCADE ON DELETE CASCADE
) engine=InnoDB;

 
 
